import{z as i,x as s,o,c as B,q as t,j as r,D as e,d as E,s as n,S as A}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Toolformer","description":"","frontmatter":{"title":"Toolformer","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/toolformer.md","filePath":"llm/toolformer.md","lastUpdated":1791413859000}'),c={name:"llm/toolformer.md"};function m(d,a,p,h,T,P){const l=s("Mermaid");return o(),B("div",null,[a[2]||(a[2]=t('<h1 id="toolformer" tabindex="-1">Toolformer <a class="header-anchor" href="#toolformer" aria-label="Permalink to &quot;Toolformer&quot;">​</a></h1><div class="epigraph"><p>不必为每个下游任务手写少样本轨迹：让模型自己在文本里插入 API 调用，只留下那些能降低未来 token 损失的调用，它就能学会何时算、何时查、何时翻译。</p><footer>—— Schick 等，Toolformer: Language Models Can Teach Themselves to Use Tools，NeurIPS 2023</footer></div><p>Timo Schick、Jane Dwivedi-Yu、Roberto Dessì、Roberta Raileanu、Maria Lomeli、Luke Zettlemoyer、Nicola Cancedda 与 Thomas Scialom（Meta AI 等）的 NeurIPS 2023 论文（arXiv:2302.04761）把工具使用收成<strong>自监督语言建模</strong>。GPT-J 6.7B 量级的模型，用每种 API 少数示范生成候选调用，执行后看是否降低后续词的负对数似然，过滤后再微调。工具包括计算器、问答系统、维基搜索、翻译（NLLB）和日历。它不是 <a href="/llm/function-calling">function calling</a> 的 JSON 信封，也不是 <a href="/llm/react">ReAct</a> 的交错 Thought 提示：推理时模型在该调用的位置自己放出特殊记号，宿主填回结果，再继续写。本篇写这条「调用必须对续写有用」的过滤，以及它与后来协议化工具调用的分工。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>语言模型擅长续写，却在算术、实时事实、时区换算上系统性失败；更小的专用模块在这些点上更强。两条现成路都不理想。一条是海量人工示范（<a href="/llm/webgpt">WebGPT</a> 一类浏览轨迹、对话里的插件标注），贵。另一条是任务已知时的少样本提示（PAL 把题写成 Python，ReAct 把题写成 Action 序列），换任务就要换示范，也无法在泛化预训练目标里学会「这段文本该不该打断去查表」。</p><p><span class="marginnote">「零样本」就是不给任何新任务的示范，直接考。Toolformer 的卖点正在于此：「该插调用」这件事在通用文本上一次学会，换新任务不用重新给例子——对比少样本提示法「换任务就换示范」的麻烦。</span></p><p>TALM（Parisi 等）已用类似自监督教模型用计算器与搜索，但落在下游微调设定。Toolformer 要的是：工具集合固定、每种只需一把示范，在通用语料上学会插入调用，零样本迁移到下游，且<strong>不牺牲</strong>作为语言模型的核心能力。</p><h3 id="调用是插入-不是另开一个-agent-循环" tabindex="-1">调用是插入，不是另开一个 Agent 循环 <a class="header-anchor" href="#调用是插入-不是另开一个-agent-循环" aria-label="Permalink to &quot;调用是插入，不是另开一个 Agent 循环&quot;">​</a></h3><p>文本被写成：普通 token，遇到需要工具处插入 <code>⟨API⟩</code> 参数 <code>→</code> 结果 <code>⟨/API⟩</code> 一类括号，然后继续原文。训练时结果来自真 API；推理时模型生成左括号与参数，宿主执行，把结果字符串写回，模型再生成后续。没有多步规划器，没有用户可见的 Thought 频道。该不该调用，由「这段插入是否让后面更好预测」决定，而不是由任务标签决定。</p><p><span class="marginnote">特殊记号与 JSON Schema 不是同一层。产品若要把 Toolformer 接到 OpenAI 式 <code>tools</code> 字段，需要一层模板把括号格式译成 <code>tool_calls</code>。评测「会不会用工具」时不要混用两种解码约束。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对每个 API：用少量上下文示范提示模型，在语料片段上采样可能的插入位置与参数（可打分、可多样本）。执行 API，得到结果字符串。对每个候选，比较「插入调用并看到结果」与「不插入」两种前缀下，<strong>未来 token</strong> 的损失。仅当</p> \\[L_i^{+} \\lt L_i - \\tau \\]<p>时保留该调用（\\(\\tau\\) 为阈值，避免无信息的装饰性调用）。过滤后的文本当作微调语料，目标仍是下一个 token，模型因此同时学习：调用位置、参数怎么写、结果怎么读进后续句。推理用贪心或常规解码；当采样到调用起始符，暂停，执行，续写。</p><p><span class="marginnote">数字实例：阈值 \\(\\tau\\) 像考试的「进步分数线」。若插入计算器结果让后面 20 个词的总损失从 30 降到 24，降幅 6 超过 \\(\\tau\\)，这次调用就被留下；若只降 0.5，多半是装饰性的，扔掉。</span></p><p>工具语义（论文设定，均为合法只读或纯计算工作流）：计算器解算术表达式；问答与维基检索补事实；翻译处理跨语句；日历处理「今天/明天」一类需要系统日期的指代。不引入任意 URL 抓取或凭证操作。主实验：GPT-J 6.7B 经此微调后，在若干数学、事实、时序任务上零样本大幅超过同尺寸基座，部分指标可与大两个数量级的 GPT-3 相比，同时在语言建模保持上不崩。</p>',16)),(o(),r(A,null,{default:e(()=>[n(l,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E8%AF%AD%E6%96%99%E7%89%87%E6%AE%B5%22%5D%20--%3E%20GEN%5B%22%E5%B0%91%E6%A0%B7%E6%9C%AC%E9%87%87%E6%A0%B7%E5%80%99%E9%80%89%20API%22%5D%0A%20%20GEN%20--%3E%20EX%5B%22%E6%89%A7%E8%A1%8C%E5%B7%A5%E5%85%B7%E5%BE%97%E7%BB%93%E6%9E%9C%22%5D%0A%20%20EX%20--%3E%20FLT%5B%22%E6%AF%94%E8%BE%83%E6%9C%AA%E6%9D%A5%20token%20%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20FLT%20--%3E%7CL%2B%20%E8%B6%B3%E5%A4%9F%E4%BD%8E%7C%20KEEP%5B%22%E4%BF%9D%E7%95%99%E6%8F%92%E5%85%A5%22%5D%0A%20%20FLT%20--%3E%7C%E5%90%A6%E5%88%99%7C%20DROP%5B%22%E4%B8%A2%E5%BC%83%22%5D%0A%20%20KEEP%20--%3E%20FT%5B%22%E8%AF%AD%E8%A8%80%E5%BB%BA%E6%A8%A1%E5%BE%AE%E8%B0%83%22%5D%0A%20%20FT%20--%3E%20INF%5B%22%E6%8E%A8%E7%90%86%EF%BC%9A%E7%94%9F%E6%88%90%E6%8B%AC%E5%8F%B7%E5%88%99%E8%B0%83%E7%94%A8%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h3 id="过滤比示范更重要" tabindex="-1">过滤比示范更重要 <a class="header-anchor" href="#过滤比示范更重要" aria-label="Permalink to &quot;过滤比示范更重要&quot;">​</a></h3><p>示范只教格式。真正抑制「每句话都搜一遍维基」的是 \\(\\tau\\)：调用必须降低后续 NLL。计算器在「需要进位的数字」处留下，在「the two of them」这种假数字处被丢掉。这与 ReAct 少样本里人工示范「何时搜」不同——监督信号来自语言模型自己的压缩目标。代价是：对未来 token 无帮助、但对用户有帮助的调用（例如先查再拒绝回答）不会被留下。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>插入调用等于在序列里加入一段<strong>由外部过程决定的 token</strong>。若这段过程输出的字符串恰好是后续文本的充分统计，NLL 下降，梯度（微调时）会强化该位置的起始符与参数模式。若 API 返回噪声或与后文无关，NLL 上升，样本被丢。模型学到的不是「工具模块的权重」，而是条件分布 \\(p(\\text{call}\\mid \\text{prefix})\\) 与 \\(p(\\text{args}\\mid \\text{call})\\)。执行永远在模型外，与 function calling 相同：生成不等于副作用已发生。</p><p><span class="marginnote">常见误区：以为微调把「计算器」装进了权重。模型学到的只是两个条件分布——什么时候该发调用符、参数怎么写；算术仍是执行器算的。删掉宿主执行，它就只剩一个「想调用」的姿势。</span></p><p>与 PAL 的差别：PAL 一次生成完整程序再执行，中间没有「结果写回再续写原文」；Toolformer 的工具是短 API，插入点在自然语言内部。与 ReAct 的差别：没有显式 Thought，也没有环境回合的奖励，只有语言建模。与 Gorilla 的差别：工具集合小而固定，不检索海量 API 文档。</p>',6)),(o(),r(A,null,{default:e(()=>[n(l,{id:"mermaid-63",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E5%90%8C%E4%B8%80%E4%BB%BB%E5%8A%A1%EF%BC%8C%E5%9B%9B%E7%A7%8D%E5%81%9A%E6%B3%95%22%5D%20--%3E%20A%5B%22PAL%EF%BC%9A%E6%95%B4%E6%AE%B5%E7%A8%8B%E5%BA%8F%EF%BC%8C%E4%B8%80%E6%AC%A1%E6%89%A7%E8%A1%8C%22%5D%0A%20%20P%20--%3E%20B%5B%22ReAct%EF%BC%9AThought%20%E4%B8%8E%E5%8A%A8%E4%BD%9C%E4%BA%A4%E9%94%99%EF%BC%8C%E6%9D%83%E9%87%8D%E5%86%BB%E7%BB%93%22%5D%0A%20%20P%20--%3E%20C%5B%22Toolformer%EF%BC%9A%E8%87%AA%E7%84%B6%E8%AF%AD%E8%A8%80%E5%86%85%E6%8F%92%E5%85%A5%E7%9F%AD%20API%22%5D%0A%20%20P%20--%3E%20D%5B%22Gorilla%EF%BC%9A%E6%A3%80%E7%B4%A2%E6%B5%B7%E9%87%8F%20API%20%E6%96%87%E6%A1%A3%E5%86%8D%E8%B0%83%E7%94%A8%22%5D%0A%20%20C%20--%3E%20E%5B%22%E7%9B%91%E7%9D%A3%E4%BF%A1%E5%8F%B7%EF%BC%9A%E6%9C%AA%E6%9D%A5%20token%20%E7%9A%84%20NLL%20%E4%B8%8B%E9%99%8D%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">Schick 等同时列出 Eric Hambro 等作者变体；引用以 NeurIPS 2023 论文为准。不要把 2023 年 GPT-J 实验写成「GPT-4 function calling 的训练配方」。</span></p><h3 id="零样本迁移依赖工具仍可用" tabindex="-1">零样本迁移依赖工具仍可用 <a class="header-anchor" href="#零样本迁移依赖工具仍可用" aria-label="Permalink to &quot;零样本迁移依赖工具仍可用&quot;">​</a></h3><p>下游任务若仍能打到同一计算器或同一维基端点，插入策略可以迁移。若生产环境换了搜索引擎排序或禁止该 API，微调过的起始符仍会触发调用，宿主必须失败回填，否则模型会把空结果当事实。论文评测是任务准确率加 LM 保持，不是 <a href="/llm/bfcl">BFCL</a> 的 AST 分项。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Toolformer 不解决工具爆炸：每种 API 要跑一遍「采样–执行–过滤」，维基与问答的执行成本在数据构造期一次性付清。多步依赖（先搜 ID 再取字段）不是主合同，嵌套调用与并行调用要另做解码。安全上，白名单必须在宿主；模型只能从示范过的 API 名里选。后续产品把「自监督插入」换成指令数据里的 tool 角色，见 function calling 文；需要海量变体 API 时见 <a href="/llm/gorilla">Gorilla</a>。需要浏览器引用链时见 WebGPT。不要在这篇里接任意网页操作或攻击性爬虫——原文工具是计算与检索。</p><p><span class="marginnote">出处：Schick, Dwivedi-Yu, Dessì, Raileanu, Lomeli, Zettlemoyer, Cancedda, Scialom，<em>Toolformer: Language Models Can Teach Themselves to Use Tools</em>，NeurIPS 2023，arXiv:2302.04761。相关：TALM；协议层见 OpenAI tools。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Toolformer 用未来 token 损失过滤自监督 API 插入，再微调语言模型。</li><li>每种工具只需少量格式示范；推理时遇起始符由宿主执行并回填。</li><li>它教「何时调用对续写有用」，不教 JSON Schema，也不是多步 Agent 循环。</li><li>出处：Schick et al.，NeurIPS 2023。</li></ul>',8))])}const C=i(c,[["render",m]]);export{u as __pageData,C as default};
